# Reply format

Reply with one JSON object and nothing else. It must match this JSON schema:
```json
{"$defs": {"DocOut": {"properties": {"filename": {"type": "string"}, "doc_type": {"type": "string"}, "language": {"type": "string"}}, "required": ["filename", "doc_type", "language"], "type": "object"}, "EvidenceOut": {"properties": {"document": {"description": "filename, or 'description'", "type": "string"}, "quote": {"type": "string"}, "relevance": {"type": "string"}}, "required": ["document", "quote", "relevance"], "type": "object"}}, "properties": {"outcome": {"enum": ["APPROVE", "DENY", "UNCERTAIN"], "type": "string"}, "payout": {"anyOf": [{"type": "number"}, {"type": "null"}], "default": null}, "currency": {"default": "EUR", "type": "string"}, "confidence": {"maximum": 1, "minimum": 0, "type": "number"}, "summary": {"type": "string"}, "reasoning": {"type": "string"}, "evidence": {"items": {"$ref": "#/$defs/EvidenceOut"}, "type": "array"}, "concerns": {"items": {"type": "string"}, "type": "array"}, "documents": {"items": {"$ref": "#/$defs/DocOut"}, "type": "array"}}, "required": ["outcome", "confidence", "summary", "reasoning"], "type": "object"}
```
Its shape, with placeholder values:
```json
{
 "outcome": "APPROVE|DENY|UNCERTAIN",
 "payout": 0.0,
 "currency": "...",
 "confidence": 0.0,
 "summary": "...",
 "reasoning": "...",
 "evidence": [
  {
   "document": "...",
   "quote": "...",
   "relevance": "..."
  }
 ],
 "concerns": [
  "..."
 ],
 "documents": [
  {
   "filename": "...",
   "doc_type": "...",
   "language": "..."
  }
 ]
}
```
